Given a matrix mat[][] having n rows and m columns. The task is to find unique elements in the matrix i.e., those elements which are not repeated in the matrix or those elements whose frequency is 1. Examples: Input: mat[][] = [[2, 1, 4, 3],                  [1, 2, 3, 2],                  [3, 6, 2, 3],                  [5, 2, 5, 3]]Output: 4 6Input:mat[][] = [[1, 2],                  [2, 1]]Output: No unique element in the matrixApproach:The idea is to create an empty hashmap and traverse through all the elements of the matrix and update the count of element in hashmap. After traversal if count of element is 1 it is unique else it is not.
            C++

    // C++ program to find unique element in matrix
#include <bits/stdc++.h>
using namespace std;

// function that calculate unique element
int unique(vector<vector<int>> &mat) {

    // declare map for hashing
    int n = mat.size();
    int m = mat[0].size();

    unordered_map<int, int> mp;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)

            // increase freq of mat[i][j] in map
            mp[(mat[i][j])]++;

    int flag = false;

    for (auto p : mp) {

        if (p.second == 1) {

            cout << p.first << " ";
            flag = 1;
        }
    }

    if (!flag) {
        cout << "No unique element in the matrix";
    }
}

int main() {

    vector<vector<int>> mat = {{1, 2, 3, 20},
                               {5, 6, 20, 25},
                               {1, 3, 5, 6},
                               {6, 7, 8, 15}};
    unique(mat);
    return 0;
}


            Java

    // Java program to find unique element in matrix
import java.util.*;

class GfG {

    // Function that calculates unique element
    static void unique(int[][] mat) {

        // Declare map for hashing
        int n = mat.length;
        int m = mat[0].length;

        Map<Integer, Integer> mp = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {

                // Increase freq of mat[i][j] in map
                mp.put(mat[i][j],
                       mp.getOrDefault(mat[i][j], 0) + 1);
            }
        }

        boolean flag = false;

        // Print unique element
        for (Map.Entry<Integer, Integer> entry :
             mp.entrySet()) {
            if (entry.getValue() == 1) {
                System.out.print(entry.getKey() + " ");
                flag = true;
            }
        }

        if (!flag) {
            System.out.println(
                "No unique element in the matrix");
        }
    }

    public static void main(String[] args) {
        int[][] mat = { { 1, 2, 3, 20 },
                        { 5, 6, 20, 25 },
                        { 1, 3, 5, 6 },
                        { 6, 7, 8, 15 } };
        unique(mat);
    }
}


