            C#

    // C# program to find unique element in matrix
using System;
using System.Collections.Generic;

class GfG {

    // Function that calculates unique element
    static void Unique(int[, ] mat) {

        // Declare map for hashing
        int n = mat.GetLength(0);
        int m = mat.GetLength(1);

        Dictionary<int, int> mp
            = new Dictionary<int, int>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {

                // Increase freq of mat[i, j] in map
                if (mp.ContainsKey(mat[i, j])) {
                    mp[mat[i, j]]++;
                }
                else {
                    mp[mat[i, j]] = 1;
                }
            }
        }

        bool flag = false;

        // Print unique element
        foreach(var p in mp) {
            if (p.Value == 1) {
                Console.Write(p.Key + " ");
                flag = true;
            }
        }

        if (!flag) {
            Console.WriteLine(
                "No unique element in the matrix");
        }
    }

    public static void Main(string[] args) {
        int[, ] mat = { { 1, 2, 3, 20 },
                        { 5, 6, 20, 25 },
                        { 1, 3, 5, 6 },
                        { 6, 7, 8, 15 } };

        Unique(mat);
    }
}


